// Collection-level pre-request script
// Auto-refreshes the OAuth access token before every request
// Skips token refresh for the Auth folder's 'Get Token' request itself
if (req.getName() === 'Get Token') { return; }

const tokenUrl = bru.getEnvVar('baseUrl') + '/oauth2/v1/token';
const clientId = bru.getEnvVar('clientId');
const clientSecret = bru.getEnvVar('clientSecret');
const tokenExpiry = bru.getEnvVar('tokenExpiry');
const currentTime = Date.now();

if (!bru.getEnvVar('accessToken') || bru.getEnvVar('accessToken') == undefined || !tokenExpiry || currentTime >= parseInt(tokenExpiry)) {
    const credentials = btoa(clientId + ':' + clientSecret);
    await bru.sendRequest({
        url: tokenUrl,
        method: 'POST',
        headers: {
            'Authorization': 'Basic ' + credentials,
            "Content-Type": "application/x-www-form-urlencoded"
        },
        data: {
            "grant_type": 'client_credentials',
            "scope": 'athena/service/Athenanet.MDP.*'
        }
    }, async function(err, response) {
        if (!err && response.status === 200) {
            const json = response.data;
            bru.setEnvVar('accessToken', json.access_token);
            const expiryTime = Date.now() + (json.expires_in - 60) * 1000;
            bru.setEnvVar('tokenExpiry', expiryTime.toString());
        } else {
            console.error('Token refresh failed:', err, response && response.data);
        }
    });
}
